/* ---------- 详情写操作（参考 G 端 + 原型 act-bar / sheet） ---------- */
type SheetKind = 'report' | 'progress' | 'finish'
const sheetKind = ref<SheetKind | null>(null)
const sheetText = ref('')
const SHEET_META: Record<SheetKind, { title: string; hint: string; placeholder: string; target?: string }> = {
  report: { title: '上报至上一级主管部门', hint: '', placeholder: '请填写上报说明，如本级处置能力不足的原因与请求事项', target: '街道防汛应急中心' },
  progress: { title: '进度反馈', hint: '反馈内容将写入处置协同记录，物业企业可实时查看。', placeholder: '请说明当前处置进展，如已到场队伍、已调拨物资、预计完成时间' },
  finish: { title: '确认完结该工单', hint: '完结后工单状态置为「已完成」，物业企业与上级主管部门均不可再操作。', placeholder: '请填写处置结果，如积水已排空、险情已消除' },
}
const sheetMeta = computed(() => sheetKind.value ? SHEET_META[sheetKind.value] : null)
function openSheet(kind: SheetKind) { sheetKind.value = kind; sheetText.value = '' }
function closeSheet() { sheetKind.value = null }

const showActBar = computed(() => currentRole.value === 'gov' && activeScreen.value === 'detail' && !!current.value)
const actMainMode = computed<'accept' | 'finish' | 'none'>(() => {
  const s = current.value?.status
  if (s === 'pending') return 'accept'
  if (s === 'accepted' || s === 'processing') return 'finish'
  return 'none'
})
const actMainText = computed(() => {
  const m = actMainMode.value
  return m === 'accept' ? '立即受理' : m === 'finish' ? '标记完结' : '该工单已完结'
})
const actSubDisabled = computed(() => {
  const s = current.value?.status
  return { report: s === 'done', progress: s === 'pending' || s === 'done', finish: s === 'pending' || s === 'done' }
})

function nowShortTime() {
  const d = new Date()
  const p = (n: number) => (n < 10 ? '0' : '') + n
  return `${p(d.getMonth() + 1)}-${p(d.getDate())} ${p(d.getHours())}:${p(d.getMinutes())}`
}

/** 统一写入：接真实接口（G 端同款）/ 否则本地状态流转；成功后追加协同节点并同步列表 */
async function pushWriteNode(
  act: string, text: string, nextStatus: string | undefined,
  endpoint?: string, payload?: Record<string, unknown>,
) {
  const o = current.value
  if (!o) return
  if (endpoint && isConfigured() && !isDemo.value) {
    try {
      await request(`/v2.0/safety/flood/rescue/${encodeURIComponent(o.id)}/${endpoint}`, {
        method: 'POST', data: payload,
      })
    } catch {
      showToast('写入接口未成功，已在本地记录')
    }
  }
  o.nodes.push({ src: '属地街道', act, time: nowShortTime(), text })
  if (nextStatus) o.status = nextStatus
  const idx = orders.value.findIndex(x => x.id === o.id)
  if (idx >= 0) orders.value[idx] = { ...o }
  showToast(isDemo.value ? `${act}已记录（演示数据，未写入后端）` : `${act}已提交`)
}

function acceptOrder() {
  if (actMainMode.value !== 'accept') return
  void pushWriteNode(
    '受理', '街道防汛应急中心已受理该求援工单，正协调机动抢险队伍与排涝设备前往现场。',
    'accepted', 'accept',
  )
}
function onActMain() {
  if (actMainMode.value === 'accept') acceptOrder()
  else if (actMainMode.value === 'finish') openSheet('finish')
}
async function confirmSheet() {
  const kind = sheetKind.value
  if (!kind) return
  const text = sheetText.value.trim()
  if (!text) { showToast('请填写说明内容'); return }
  if (kind === 'report') {
    await pushWriteNode('上报至上级', text, undefined, 'report', { content: text })
  } else if (kind === 'progress') {
    await pushWriteNode('进度反馈', text, current.value?.status === 'accepted' ? 'processing' : undefined, 'feedback', { content: text, attachUrl: '', attachName: '' })
  } else {
    await pushWriteNode('完结', text, 'done', 'finish', { content: text })
  }
  closeSheet()
}

function callPhone(phone: string) { showToast('调起系统拨号：' + phone) }
function goWorkbenchEntry() { goto('list') }

onMounted(loadList)
</script>

