/* ---------- 角色判定：G 端（主管部门）才显示写操作，取不到角色一律隐藏 ---------- */
const isBEnd = ref(false)
const roleReady = ref(false)
function applyRole(keys: string[]) {
  if (!keys.length) return false
  isBEnd.value = keys.some(k => k === 'wyqy' || k === 'wyqygly')
  roleReady.value = true
  return true
}
async function refreshRole() {
  try {
    const u = await queryUser()
    const keys = [
      ...((u?.roles ?? []) as Array<{ roleKey?: string }>).map(r => String(r?.roleKey ?? '')),
      ...((u?.roleKeys ?? []) as unknown[]).map(k => String(k ?? '')),
    ].filter(Boolean)
    if (applyRole(keys)) return
  } catch { /* 接口失败回退缓存 */ }
  const cached = getLoginUser()
  const cachedKeys = [
    ...(cached?.roles ?? []).map(r => String(r?.roleKey ?? '')),
    ...(cached?.roleKeys ?? []).map(k => String(k ?? '')),
  ].filter(Boolean)
  applyRole(cachedKeys)
}

/* ---------- 详情写操作：受理 / 上报 / 进度反馈 / 完结（真实接口 + 本地刷新） ---------- */
type SheetKind = 'report' | 'progress' | 'finish'
const sheetKind = ref<SheetKind | null>(null)
const sheetText = ref('')
const busy = ref(false)
const SHEET_META: Record<SheetKind, { title: string; hint: string; placeholder: string; target?: string }> = {
  report: { title: '上报至上一级主管部门', placeholder: '请填写上报说明，如本级处置能力不足的原因与请求事项', target: '街道防汛应急中心' },
  progress: { title: '进度反馈', hint: '反馈内容将写入处置协同记录，物业企业可实时查看。', placeholder: '请说明当前处置进展，如已到场队伍、已调拨物资、预计完成时间' },
  finish: { title: '确认完结该工单', hint: '完结后工单状态置为「已完成」，物业企业与上级主管部门均不可再操作。', placeholder: '请填写处置结果，如积水已排空、险情已消除' },
}
const sheetMeta = computed(() => sheetKind.value ? SHEET_META[sheetKind.value] : null)
const showActBar = computed(() => roleReady.value && !isBEnd.value && !!current.value)
const actMainMode = computed<'accept' | 'finish' | 'none'>(() => {
  const s = current.value?.status
  if (s === 'pending') return 'accept'
  if (s === 'accepted' || s === 'processing') return 'finish'
  return 'none'
})
const actMainText = computed(() => {
  const m = actMainMode.value
  return m === 'accept' ? '立即受理' : m === 'finish' ? '标记完结' : '该工单已完结'
})
const actSubDisabled = computed(() => {
  const s = current.value?.status
  return { report: s === 'done', progress: s === 'pending' || s === 'done', finish: s === 'pending' || s === 'done' }
})
function openSheet(kind: SheetKind) { sheetKind.value = kind; sheetText.value = '' }
function closeSheet() { sheetKind.value = null }
function nowShortTime() {
  const d = new Date()
  const p = (n: number) => (n < 10 ? '0' : '') + n
  return `${p(d.getMonth() + 1)}-${p(d.getDate())} ${p(d.getHours())}:${p(d.getMinutes())}`
}

/** 统一写入：调用真实接口成功后追加协同节点并刷新详情；失败仅提示，不改本地状态 */
async function pushWriteNode(
  act: string, text: string, endpoint: string,
  payload?: Record<string, unknown>, nextStatus?: string,
) {
  const o = current.value
  if (!o || busy.value) return
  busy.value = true
  try {
    if (!isConfigured()) throw new Error('接口未配置')
    const qs = payload ? `?${Object.keys(payload).map(k => `${encodeURIComponent(k)}=${encodeURIComponent(String(payload[k] ?? ''))}`).join('&')}` : ''
    await request(`/v2.0/safety/flood/rescue/${encodeURIComponent(o.id)}/${endpoint}${qs}`, { method: 'POST', data: payload && endpoint === 'feedback' ? payload : undefined })
    o.nodes.push({ src: '属地街道', act, time: nowShortTime(), text })
    if (nextStatus) o.status = nextStatus
    uni.showToast({ title: `${act}成功`, icon: 'success' })
    await loadDetail(o.id)
  } catch (e) {
    uni.showToast({ title: e instanceof Error ? e.message : `${act}未成功`, icon: 'none' })
  } finally {
    busy.value = false
  }
}
function onActMain() {
  if (busy.value) return
  if (actMainMode.value === 'accept') {
    void pushWriteNode('受理', '街道防汛应急中心已受理该求援工单，正协调机动抢险队伍与排涝设备前往现场。', 'accept', undefined, 'accepted')
  } else if (actMainMode.value === 'finish') {
    openSheet('finish')
  }
}
async function confirmSheet() {
  if (busy.value) return
  const kind = sheetKind.value
  if (!kind) return
  const text = sheetText.value.trim()
  if (!text) { uni.showToast({ title: '请填写说明内容', icon: 'none' }); return }
  if (kind === 'report') {
    await pushWriteNode('上报至上级', text, 'report', { content: text })
  } else if (kind === 'progress') {
    await pushWriteNode('进度反馈', text, 'feedback', { content: text, attachUrl: '', attachName: '' }, 'processing')
  } else {
    await pushWriteNode('完结', text, 'finish', { content: text }, 'done')
  }
  if (!busy.value) closeSheet()
}

onLoad(options => {
  void refreshRole()
  loadDetail(String(options?.id ?? ''))
})

